lemma sign_dichotomy_Iio {Q : R[X]} {ys : List R}
    (h : SignConstantOnGaps Q ys) {c : R} (hle : ∀ r ∈ ys, c ≤ r) :
    (∀ x ∈ Set.Iio c, 0 < Q.eval x) ∨ (∀ x ∈ Set.Iio c, Q.eval x < 0)

lemma sign_dichotomy_Ioi {Q : R[X]} {ys : List R}
