theorem mem_realizationOverFinset [Fintype ι] {σ : SignCondition ι} {P : R[X]}
    {Q : ι → R[X]} (hP : P ≠ 0) {x : R} :
    x ∈ σ.realizationOverFinset P Q ↔ x ∈ σ.realizationOver P Q

theorem coeff_mul_zero_of_nonneg {x y : HahnSeries ℚ K}
    (hx : 0 ≤ x.orderTop) (hy : 0 ≤ y.orderTop) :
    (x * y).coeff 0 = x.coeff 0 * y.coeff 0

lemma multiset_product_map {α α' β β' : Type*}
    (s : Multiset α) (t : Multiset β) (f : α → α') (g : β → β') :
    (s.map f) ×ˢ (t.map g) = (s ×ˢ t).map (Prod.map f g)

