theorem isFiniteMapping_fiber_finite {Ps : Finset (MvPolynomial (Fin (n + 1)) K)}
    {Qs : Finset (MvPolynomial (Fin n) K)} (h : IsFiniteMapping C Ps Qs) (y : Fin n → C) :
    ((Fin.tail : (Fin (n + 1) → C) → (Fin n → C)) ⁻¹' {y} ∩ zerOfFinset C Ps).Finite

theorem IsFiniteMapping.isFiniteMappingChain {C : Type*} [Field C] [Algebra K C] {k' : ℕ}
    {P : Finset (MvPolynomial (Fin (k' + 1)) K)} {T : Finset (MvPolynomial (Fin k') K)}
    (h : IsFiniteMapping C P T) : IsFiniteMappingChain C k' 1 P T

@[simp] theorem isFiniteMappingChain_zero (C : Type*) [Field C] [Algebra K C] {k' : ℕ}
    (P : Finset (MvPolynomial (Fin (k' + 0)) K)) (T : Finset (MvPolynomial (Fin k') K)) :
    IsFiniteMappingChain C k' 0 P T ↔ P = T

theorem exists_finset_zerOfIdeal (I : Ideal (MvPolynomial (Fin k) K)) :
    ∃ P : Finset (MvPolynomial (Fin k) K),
      zerOfIdeal (L := L) I = {x : Fin k → L | ∀ p ∈ P, MvPolynomial.aeval x p = 0}
